begin;
set local search_path='';
set local timezone='UTC';
set local statement_timeout='45s';
set local lock_timeout='5s';
select pg_catalog.set_config('alq_f1a.case_run', :'RUN_ID', false);
select pg_catalog.set_config('alq_f1a.case_name', :'CASE_NAME', false);
select pg_catalog.set_config('alq_f1a.case_side', :'SIDE', false);

create temporary table alq_f1a_qualification_context(run_id uuid primary key);
create temporary table alq_f1a_peer(pid integer primary key);
create temporary table alq_f1a_case_result(
  status text not null,
  financial_success boolean not null,
  residual_rows integer not null check(residual_rows=0));

create function pg_temp.alq_f1a_run_uuid()
returns uuid language sql stable set search_path=''
as $fn$
  select (substr(current_setting('alq_f1a.case_run'),1,8)||'-'||
          substr(current_setting('alq_f1a.case_run'),9,4)||'-'||
          substr(current_setting('alq_f1a.case_run'),13,4)||'-'||
          substr(current_setting('alq_f1a.case_run'),17,4)||'-'||
          substr(current_setting('alq_f1a.case_run'),21,12))::uuid
$fn$;
create function pg_temp.alq_f1a_id(p_label text)
returns uuid language sql stable set search_path=''
as $fn$
  select (substr(md5(current_setting('alq_f1a.case_run')||':'||p_label),1,8)||'-'||
          substr(md5(current_setting('alq_f1a.case_run')||':'||p_label),9,4)||'-4'||
          substr(md5(current_setting('alq_f1a.case_run')||':'||p_label),14,3)||'-8'||
          substr(md5(current_setting('alq_f1a.case_run')||':'||p_label),18,3)||'-'||
          substr(md5(current_setting('alq_f1a.case_run')||':'||p_label),21,12))::uuid
$fn$;
insert into pg_temp.alq_f1a_qualification_context
values(pg_temp.alq_f1a_run_uuid());

do $alq_f1a_setup$
declare
  v_payload jsonb:=jsonb_build_object('fixture',true,'run',
    current_setting('alq_f1a.case_run'));
begin
  if current_setting('alq_f1a.case_side')<>'A' then return; end if;

  insert into auth.users(id,email)
  values(pg_temp.alq_f1a_id('actor_auth'),
    'f1a-local-'||current_setting('alq_f1a.case_run')||'.invalid')
  on conflict(id) do nothing;
  insert into alq.alq_parte(id,tipo_persona,nombre)
  values
    (pg_temp.alq_f1a_id('actor_part'),'fisica','F1A concurrency actor'),
    (pg_temp.alq_f1a_id('tenant'),'fisica','F1A concurrency tenant'),
    (pg_temp.alq_f1a_id('owner'),'fisica','F1A concurrency owner')
  on conflict(id) do nothing;
  insert into alq.alq_parte_usuario(id,parte_id,auth_user_id,vigencia)
  values(pg_temp.alq_f1a_id('actor_pu'),pg_temp.alq_f1a_id('actor_part'),
    pg_temp.alq_f1a_id('actor_auth'),
    tstzrange('2020-01-01 00:00:00+00',null,'[)'))
  on conflict(id) do nothing;
  insert into alq.alq_capacidad_admin(
    id,parte_usuario_id,capacidad,vigencia)
  values(pg_temp.alq_f1a_id('actor_cap'),pg_temp.alq_f1a_id('actor_pu'),
    'supervisor',tstzrange('2020-01-01 00:00:00+00',null,'[)'))
  on conflict(id) do nothing;
  insert into alq.alq_propiedad(
    id,direccion,direccion_norm,ciudad,ciudad_norm,provincia)
  values(pg_temp.alq_f1a_id('property'),
    'F1A concurrency '||current_setting('alq_f1a.case_run'),
    'f1a concurrency '||current_setting('alq_f1a.case_run'),
    'Local','local','Chubut')
  on conflict(id) do nothing;
  insert into alq.alq_contrato(
    id,propiedad_id,inquilino_parte_id,inicio,fin_pactado,estado)
  values(pg_temp.alq_f1a_id('contract'),pg_temp.alq_f1a_id('property'),
    pg_temp.alq_f1a_id('tenant'),'2026-01-01','2026-12-31','vigente')
  on conflict(id) do nothing;
  insert into alq.alq_contrato_version(
    id,contrato_id,vigencia,monto,moneda,dia_pago_desde,dia_pago_hasta,
    formula_punitorio_version,metodo_prorrateo,regla_redondeo,
    regla_pago_otra_moneda)
  values(pg_temp.alq_f1a_id('contract_version'),pg_temp.alq_f1a_id('contract'),
    tstzrange('2026-01-01 00:00:00+00',null,'[)'),100,'ARS',1,10,
    'f1a-v1','dias_reales','centavos','prohibido')
  on conflict(id) do nothing;
  insert into alq.alq_periodo(
    id,contrato_id,contrato_version_id,secuencia,rango,vence_at,
    moneda,monto_emitido,snapshot_regla)
  values(pg_temp.alq_f1a_id('period'),pg_temp.alq_f1a_id('contract'),
    pg_temp.alq_f1a_id('contract_version'),1,
    daterange('2026-01-01','2026-02-01','[)'),
    '2026-01-10 12:00:00+00','ARS',100,'{"f1a":true}'::jsonb)
  on conflict(id) do nothing;
  insert into alq.alq_cuenta_custodia(
    id,banco_billetera,identificador,moneda,activa)
  values
    (pg_temp.alq_f1a_id('account_a'),'F1A',
      'A-'||current_setting('alq_f1a.case_run'),'ARS',true),
    (pg_temp.alq_f1a_id('account_b'),'F1A',
      'B-'||current_setting('alq_f1a.case_run'),'ARS',true)
  on conflict(id) do nothing;
  insert into alq.alq_operacion(
    id,request_id,operacion,payload_normalizado,firma_sha256,
    estado,actor_parte_usuario_id,preparada_at)
  values(pg_temp.alq_f1a_id('base_op'),pg_temp.alq_f1a_id('base_request'),
    'd0_fixture',v_payload,alq_private.alq_firma_v1('d0_fixture',v_payload),
    'preparada',pg_temp.alq_f1a_id('actor_pu'),clock_timestamp())
  on conflict(id) do nothing;
  insert into alq.alq_cargo(
    id,propiedad_id,contrato_id,periodo_id,deudor_parte_id,
    acreedor_parte_id,ambito,concepto,moneda,monto,vence_at,origen,
    operacion_id,snapshot_regla,saldo_pendiente)
  values(pg_temp.alq_f1a_id('cargo'),pg_temp.alq_f1a_id('property'),
    pg_temp.alq_f1a_id('contract'),pg_temp.alq_f1a_id('period'),
    pg_temp.alq_f1a_id('tenant'),pg_temp.alq_f1a_id('owner'),
    'custodiada','alquiler_periodo','ARS',100,'2026-01-10 12:00:00+00',
    'admin',pg_temp.alq_f1a_id('base_op'),'{"f1a":true}'::jsonb,100)
  on conflict(id) do nothing;
  insert into alq.alq_transaccion_caja(
    id,direccion,ambito,contraparte_parte_id,beneficiario_parte_id,
    cuenta_custodia_id,moneda,monto,fecha,medio,estado,operacion_id)
  values(pg_temp.alq_f1a_id('original_tx'),'entrada','custodiada',
    pg_temp.alq_f1a_id('tenant'),pg_temp.alq_f1a_id('owner'),
    pg_temp.alq_f1a_id('account_a'),'ARS',100,
    '2026-01-05 12:00:00+00','transferencia','confirmada',
    pg_temp.alq_f1a_id('base_op'))
  on conflict(id) do nothing;
  insert into alq.alq_credito(
    id,parte_id,contrato_id,moneda,monto_original,saldo_pendiente,
    transaccion_origen_id,operacion_id)
  values(pg_temp.alq_f1a_id('credit'),pg_temp.alq_f1a_id('tenant'),
    pg_temp.alq_f1a_id('contract'),'ARS',100,100,
    pg_temp.alq_f1a_id('original_tx'),pg_temp.alq_f1a_id('base_op'))
  on conflict(id) do nothing;
  insert into alq.alq_deposito(
    id,contrato_id,moneda,monto_constituido,custodia_parte_id)
  values(pg_temp.alq_f1a_id('deposit'),pg_temp.alq_f1a_id('contract'),
    'ARS',100,pg_temp.alq_f1a_id('owner'))
  on conflict(id) do nothing;
  insert into alq.alq_aplicacion(
    id,transaccion_id,cargo_id,importe_origen,moneda_origen,
    importe_destino,moneda_destino,operacion_id)
  values(pg_temp.alq_f1a_id('base_app'),pg_temp.alq_f1a_id('original_tx'),
    pg_temp.alq_f1a_id('cargo'),60,'ARS',60,'ARS',
    pg_temp.alq_f1a_id('base_op'))
  on conflict(id) do nothing;
  set constraints all immediate;
  set constraints all deferred;
end
$alq_f1a_setup$;
commit;

begin;
do $alq_f1a_wait_setup$
declare v_deadline timestamptz:=clock_timestamp()+interval '10 seconds';
begin
  loop
    exit when exists(
      select 1 from alq.alq_operacion
      where id=pg_temp.alq_f1a_id('base_op') and estado='preparada');
    if clock_timestamp()>=v_deadline then
      raise exception 'ALQ_F1A_SETUP_PEER_TIMEOUT';
    end if;
    perform pg_catalog.pg_sleep(0.02);
  end loop;
end
$alq_f1a_wait_setup$;
select pg_catalog.set_config('request.jwt.claim.sub',
  pg_temp.alq_f1a_id('actor_auth')::text,false);
select pg_catalog.set_config('request.jwt.claim.role','authenticated',false);
select pg_catalog.set_config('request.jwt.claims',
  jsonb_build_object('sub',pg_temp.alq_f1a_id('actor_auth'),
    'role','authenticated',
    'app_metadata',jsonb_build_object('rol','admin'))::text,false);
do $alq_f1a_action_parent$
declare
  v_payload jsonb:=jsonb_build_object(
    'fixture',true,'case',current_setting('alq_f1a.case_name'),
    'side',current_setting('alq_f1a.case_side'));
begin
  insert into alq.alq_operacion(
    id,request_id,operacion,payload_normalizado,firma_sha256,
    estado,actor_parte_usuario_id,preparada_at)
  values(
    pg_temp.alq_f1a_id('action_op:'||current_setting('alq_f1a.case_name')||
      ':'||current_setting('alq_f1a.case_side')),
    pg_temp.alq_f1a_id('action_request:'||current_setting('alq_f1a.case_name')||
      ':'||current_setting('alq_f1a.case_side')),
    'd0_fixture',v_payload,alq_private.alq_firma_v1('d0_fixture',v_payload),
    'preparada',pg_temp.alq_f1a_id('actor_pu'),clock_timestamp())
  on conflict(id) do nothing;
end
$alq_f1a_action_parent$;

do $alq_f1a_retry_seed$
declare
  v_payload jsonb;
  v_pre jsonb;
  v_cancel jsonb;
begin
  if current_setting('alq_f1a.case_name')<>'REINTENTO_DOS_COMANDOS'
     or current_setting('alq_f1a.case_side')<>'A' then return; end if;
  v_payload:=jsonb_build_object(
    'cargo_fuente_ref',pg_temp.alq_f1a_id('retry_fact_ref'),
    'propiedad_id',pg_temp.alq_f1a_id('property'),
    'contrato_id',pg_temp.alq_f1a_id('contract'),
    'periodo_id',pg_temp.alq_f1a_id('period'),
    'deudor_parte_id',pg_temp.alq_f1a_id('tenant'),
    'acreedor_parte_id',pg_temp.alq_f1a_id('owner'),
    'ambito','externa','concepto','alquiler_periodo',
    'moneda','ARS','monto',20,'vence_at','2026-01-10T12:00:00Z',
    'snapshot_regla',jsonb_build_object('f1a',true));
  v_pre:=public.alq_admin_preparar_v2(
    pg_temp.alq_f1a_id('retry_seed_prepare'),
    'cargo_manual_emitir',v_payload);
  if v_pre->>'estado'<>'preparada' then
    raise exception 'ALQ_F1A_RETRY_SEED_PREPARE_INVALIDO';
  end if;
  v_cancel:=public.alq_admin_cancelar_v2(
    (v_pre->>'operacion_request_id')::uuid,
    pg_temp.alq_f1a_id('retry_seed_cancel'),'seed rechazo terminal');
  if v_cancel->>'estado'<>'rechazada'
     or v_cancel->>'codigo'<>'ALQ_F1A_CANCELADA' then
    raise exception 'ALQ_F1A_RETRY_SEED_CANCEL_INVALIDO';
  end if;
end
$alq_f1a_retry_seed$;
set constraints all immediate;
commit;

begin;
do $alq_f1a_wait_retry_seed$
declare v_deadline timestamptz:=clock_timestamp()+interval '10 seconds';
begin
  if current_setting('alq_f1a.case_name')<>'REINTENTO_DOS_COMANDOS'
     or current_setting('alq_f1a.case_side')='A' then return; end if;
  loop
    exit when exists(
      select 1
      from alq_private.alq_operacion_evento_v2 e
      where e.run_id=pg_temp.alq_f1a_run_uuid()
        and e.comando_request_id=pg_temp.alq_f1a_id('retry_seed_cancel')
        and e.codigo='ALQ_F1A_CANCELADA');
    if clock_timestamp()>=v_deadline then
      raise exception 'ALQ_F1A_RETRY_SEED_PEER_TIMEOUT';
    end if;
    perform pg_catalog.pg_sleep(0.02);
  end loop;
end
$alq_f1a_wait_retry_seed$;
select pg_catalog.set_config('application_name',pg_catalog.format(
  'alq_f1a_barrier:%s:%s:%s:READY',
  current_setting('alq_f1a.case_run'),current_setting('alq_f1a.case_name'),
  current_setting('alq_f1a.case_side')),false);
do $alq_f1a_barrier$
declare
  v_peer integer;
  v_other text:=case current_setting('alq_f1a.case_side')
    when 'A' then 'B' else 'A' end;
  v_deadline timestamptz:=clock_timestamp()+interval '10 seconds';
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'alq_f1a_barrier:signal:'||current_setting('alq_f1a.case_run')||':'||
    current_setting('alq_f1a.case_name')||':'||
    current_setting('alq_f1a.case_side'),0));
  loop
    select a.pid into v_peer
    from pg_catalog.pg_stat_activity a
    where a.datname=current_database()
      and a.pid<>pg_catalog.pg_backend_pid()
      and a.application_name=pg_catalog.format(
        'alq_f1a_barrier:%s:%s:%s:READY',
        current_setting('alq_f1a.case_run'),current_setting('alq_f1a.case_name'),
        v_other)
    order by a.pid limit 1;
    exit when found;
    if clock_timestamp()>=v_deadline then
      raise exception 'ALQ_F1A_BARRIER_PEER_TIMEOUT';
    end if;
    perform pg_catalog.pg_sleep(0.01);
  end loop;
  insert into pg_temp.alq_f1a_peer(pid) values(v_peer);
end
$alq_f1a_barrier$;
commit;

begin;
set constraints all deferred;
do $alq_f1a_real_action$
declare
  v_case text:=current_setting('alq_f1a.case_name');
  v_side text:=current_setting('alq_f1a.case_side');
  v_op uuid:=pg_temp.alq_f1a_id('action_op:'||
    current_setting('alq_f1a.case_name')||':'||
    current_setting('alq_f1a.case_side'));
  v_row uuid:=pg_temp.alq_f1a_id('row:'||
    current_setting('alq_f1a.case_name')||':'||
    current_setting('alq_f1a.case_side'));
  v_row2 uuid:=pg_temp.alq_f1a_id('row2:'||
    current_setting('alq_f1a.case_name')||':'||
    current_setting('alq_f1a.case_side'));
  v_payload jsonb;
  v_env jsonb;
  v_env2 jsonb;
  v_hecho uuid;
  v_success boolean:=false;
  v_status text;
  v_residual integer:=0;
begin
  if v_case='IDEMPOTENCIA_MISMA_CLAVE' then
    v_payload:=jsonb_build_object(
      'cargo_fuente_ref',pg_temp.alq_f1a_id('idempotent_fact_ref'),
      'propiedad_id',pg_temp.alq_f1a_id('property'),
      'contrato_id',pg_temp.alq_f1a_id('contract'),
      'periodo_id',pg_temp.alq_f1a_id('period'),
      'deudor_parte_id',pg_temp.alq_f1a_id('tenant'),
      'acreedor_parte_id',pg_temp.alq_f1a_id('owner'),
      'ambito','externa','concepto','alquiler_periodo',
      'moneda','ARS','monto',25,'vence_at','2026-01-10T12:00:00Z',
      'snapshot_regla',jsonb_build_object('f1a',true));
    v_env:=public.alq_admin_preparar_v2(
      pg_temp.alq_f1a_id('idempotent_cmd:'||v_side),
      'cargo_manual_emitir',v_payload);
    if v_env->>'estado'<>'preparada' then
      raise exception 'ALQ_F1A_IDEMPOTENCIA_PREPARE_INVALIDO';
    end if;
    perform pg_catalog.pg_sleep(0.30);
    if v_side='B' then
      v_env2:=public.alq_admin_preparar_v2(
        pg_temp.alq_f1a_id('idempotent_payload_conflict_cmd'),
        'cargo_manual_emitir',v_payload||jsonb_build_object('monto',26));
      if v_env2->>'codigo'<>'ALQ_F1A_CLAVE_PAYLOAD_CONFLICTO'
         or coalesce((v_env2->>'ok')::boolean,true) then
        raise exception 'ALQ_F1A_PAYLOAD_DISTINTO_NO_CONFLICTO';
      end if;
    end if;
    v_status:='IDEMPOTENCIA_Y_CONFLICTO_PAYLOAD';
  elsif v_case='REINTENTO_DOS_COMANDOS' then
    select e.hecho_id into v_hecho
    from alq_private.alq_operacion_evento_v2 e
    where e.comando_request_id=pg_temp.alq_f1a_id('retry_seed_cancel');
    v_env:=public.alq_admin_reintentar_v2(
      v_hecho,pg_temp.alq_f1a_id('retry_cmd:'||v_side),
      'reintento concurrente explicito');
    if not (
      (v_env->>'estado'='preparada' and coalesce((v_env->>'ok')::boolean,false))
      or (v_env->>'codigo'='ALQ_F1A_REINTENTO_YA_ACTIVO'
          and not coalesce((v_env->>'ok')::boolean,true))) then
      raise exception 'ALQ_F1A_REINTENTO_CONCURRENTE_INVALIDO';
    end if;
    perform pg_catalog.pg_sleep(0.30);
    v_status:='REINTENTO_EXPLICITO_SERIALIZADO';
  elsif v_case in ('ORDEN_LOCKS_AB','ORDEN_LOCKS_BA') then
    if (v_case='ORDEN_LOCKS_AB' and v_side='B')
       or (v_case='ORDEN_LOCKS_BA' and v_side='A') then
      perform pg_catalog.pg_sleep(0.08);
    end if;
    v_payload:=jsonb_build_object(
      'transferencia_ref',pg_temp.alq_f1a_id(
        'transfer_ref:'||v_case||':'||v_side),
      'cuenta_origen_id',case when v_side='A'
        then pg_temp.alq_f1a_id('account_a')
        else pg_temp.alq_f1a_id('account_b') end,
      'cuenta_destino_id',case when v_side='A'
        then pg_temp.alq_f1a_id('account_b')
        else pg_temp.alq_f1a_id('account_a') end,
      'contraparte_parte_id',pg_temp.alq_f1a_id('owner'),
      'beneficiario_parte_id',pg_temp.alq_f1a_id('owner'),
      'moneda','ARS','monto',10,
      'fecha','2026-01-08T12:00:00Z','medio','transferencia');
    begin
      v_env:=public.alq_admin_preparar_v2(
        pg_temp.alq_f1a_id('transfer_cmd:'||v_case||':'||v_side),
        'transferencia_in
